 workDialog=make('dialog',undefined,'comms-work-dialog');workDialog.id='comms-work-dialog';const header=make('header',undefined,'comms-work-header');header.append(make('h2','消息回执与工作记录'));const close=make('button','关闭');close.type='button';close.onclick=()=>workDialog.close();header.append(close);workDialog.append(header);
 const query=make('form',undefined,'comms-work-query-fields');query.onsubmit=event=>{event.preventDefault();loadWorkReport();};field(query,'comms-work-from','开始日期','date');field(query,'comms-work-to','结束日期','date');const personLabel=make('label','查看员工'),person=make('select');person.id='comms-work-user';personLabel.append(person);query.append(personLabel);const button=make('button','查询','comms-primary');button.type='submit';button.id='comms-work-query';query.append(button);workDialog.append(query);
 const statusNode=make('p','','comms-work-note');statusNode.id='comms-work-status';statusNode.setAttribute('role','status');workDialog.append(statusNode);const results=make('div');results.id='comms-work-results';workDialog.append(results);
 const settings=make('details',undefined,'comms-work-settings');settings.id='comms-work-settings';settings.hidden=true;settings.append(make('summary','老板：考评设置'));const form=make('form');form.onsubmit=saveWorkSettings;
 for(const [id,label]of [['comms-assessment-enabled','启用事实考评'],['comms-assessment-timeliness','启用工作时段内消息及时性']]){const node=field(form,id,label,'checkbox');node.checked=false;}
 const limits=make('div',undefined,'comms-work-query-fields');for(const [id,label]of [['comms-assessment-read-minutes','查看时限（工作分钟）'],['comms-assessment-receipt-minutes','收到时限（工作分钟）']]){const input=field(limits,id,label,'number');input.min='1';input.max='1440';input.step='1';input.required=true;}form.append(limits,make('p','当前只记录事实，不自动生成分数或扣工资。项目权重供老板后续核对规则使用。','comms-work-note'));
