let recipientDialog,recipientMembers=[],selectedRecipientIds=new Set(),recipientDraftIds=null;
function updateSelectedComposer(){const box=$('comms-selected-compose');if(!box)return;box.hidden=peer!=='selected';const selected=recipientMembers.filter(m=>selectedRecipientIds.has(m.id));$('comms-selected-summary').textContent=selected.length?'接收人：'+selected.map(m=>m.name).join('、'):'请先勾选接收人；只发送给勾选的本店员工。';$('comms-recipient-picker').disabled=!directoryLoaded;}
function updateRecipientMembers(members){recipientMembers=(members||[]).filter(m=>m.id!==me.id);const allowed=new Set(recipientMembers.map(m=>m.id));for(const selection of [selectedRecipientIds,recipientDraftIds].filter(Boolean))for(const id of selection)if(!allowed.has(id))selection.delete(id);const list=$('comms-recipient-options');if(list){list.replaceChildren();for(const member of recipientMembers){const label=make('label',undefined,'comms-pick-person'),input=make('input');input.type='checkbox';input.value=member.id;input.checked=(recipientDraftIds||selectedRecipientIds).has(member.id);input.onchange=()=>{if(!recipientDraftIds)return;if(input.checked)recipientDraftIds.add(member.id);else recipientDraftIds.delete(member.id);$('comms-recipient-pick-status').textContent='已选 '+recipientDraftIds.size+' 人；点‘选好了’确认。';};label.append(input,make('span',member.name));list.append(label);}}updateSelectedComposer();}
