function clearWorkflow(){workDialog?.close();recipientDialog?.close();selectedRecipientIds.clear();recipientDraftIds=null;recipientMembers=[];workMembers=[];workSettings=null;$('comms-work-results')?.replaceChildren();$('comms-recipient-options')?.replaceChildren();}

