async function exportLocalArchive(){const e=epoch,key=localScope?.key,control=$('comms-local-export');if(!key)return;control.disabled=true;archiveStatus('正在整理本机备份…');let url;try{const query=$('comms-local-search').value.trim().toLowerCase(),records=(await localAll(key)).filter(r=>!(r.currentCloudPayloadHash&&r.currentCloudPayloadHash!==r.payloadHash)&&(!query||((r.row.sender||'')+' '+(r.row.withdrawn?'':r.row.content||'')+' '+r.row.createdAt).toLowerCase().includes(query)));if(records.length>backupMessageLimit)throw Error('超过1000条，请先搜索姓名或日期缩小范围再导出');const parts=['{"format":"store-message-local-backup","version":1,"createdAt":'+JSON.stringify(new Date().toISOString())+',"scope":'+JSON.stringify({tenantId:localScope.tenantId,branchId:localScope.branchId,userId:localScope.userId})+',"messages":['];let size=parts[0].length;for(let i=0;i<records.length;i++){if(!localGuard(e,key))return;const r=records[i],images=[];for(const image of r.row.withdrawn?[]:r.attachments||[])images.push({id:image.id,name:image.name,mime:image.mime,sha256:image.sha256,bytes:image.bytes,data:await blobData(image.blob)});const part=(i?',':'')+JSON.stringify({message:backupMessage(r),payloadHash:r.payloadHash,savedAt:r.savedAt,serverConfirmed:r.serverConfirmed,attachments:images});size+=new TextEncoder().encode(part).length;if(size>backupLimit)throw Error('备份超过50MB，请先搜索姓名或日期分批导出');parts.push(part)}if(!localGuard(e,key))return;parts.push(']}');url=URL.createObjectURL(new Blob(parts,{type:'application/json'}));const a=make('a');a.href=url;a.download='店内消息备份-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();archiveStatus('已生成 '+records.length+' 条备份下载；请确认下载文件并妥善保管。支持同账号、本店导入，含私人消息和照片。')}catch(error){if(localGuard(e,key))archiveStatus('备份未能导出：'+error.message,true)}finally{if(url)setTimeout(()=>URL.revokeObjectURL(url),30000);control.disabled=false}}
async function validateBackup(file,key,e){if(!file||file.size>backupLimit)throw Error('备份最大50MB');let value;try{value=JSON.parse(await file.text())}catch{throw Error('不是有效的JSON备份文件')}if(!onlyKeys(value,['format','version','createdAt','scope','messages'])||value.format!=='store-message-local-backup'||value.version!==1||!Number.isFinite(Date.parse(value.createdAt))||!onlyKeys(value.scope,['tenantId','branchId','userId'])||stableScope(value.scope)?.key!==key)throw Error('备份格式、版本或账号/门店不匹配');if(!Array.isArray(value.messages)||value.messages.length>backupMessageLimit)throw Error('备份每次最多1000条');const ids=new Set(),result=[];for(const item of value.messages){if(!localGuard(e,key))throw Error('账号或门店已变化');if(!onlyKeys(item,['message','payloadHash','savedAt','serverConfirmed','attachments'])||!onlyKeys(item.message,backupMessageKeys)||!/^[a-f0-9]{64}$/.test(item.payloadHash)||!Number.isFinite(Date.parse(item.savedAt))||typeof item.serverConfirmed!=='boolean'||!Array.isArray(item.attachments)||item.attachments.length>3)throw Error('备份消息结构不正确');const row=item.message;if(typeof row.id!=='string'||!row.id||row.id.length>160||ids.has(row.id)||typeof row.content!=='string'||row.content.length>1000||typeof row.senderId!=='string'||typeof row.sender!=='string'||typeof row.recipientId!=='string'||!Number.isSafeInteger(row.sequence)||row.sequence<1||!Number.isFinite(Date.parse(row.createdAt))||!Array.isArray(row.attachments)||row.attachments.length!==item.attachments.length||typeof row.withdrawn!=='boolean'||typeof row.important!=='boolean'||!['chat','work'].includes(row.kind))throw Error('备份消息字段不正确');ids.add(row.id);const attachments=[];for(let i=0;i<item.attachments.length;i++){const image=item.attachments[i],meta=row.attachments[i];if(!onlyKeys(image,['id','name','mime','sha256','bytes','data'])||!onlyKeys(meta,['id','name','mime','sha256','bytes'])||['id','name','mime','bytes','sha256'].some(key=>meta[key]!==image[key])||typeof image.id!=='string'||typeof image.name!=='string'||image.name.length>120||!allowedImageTypes.has(image.mime)||!Number.isSafeInteger(image.bytes)||image.bytes<1||image.bytes>250000||!/^[a-f0-9]{64}$/.test(image.sha256)||typeof image.data!=='string')throw Error('备份照片结构不正确');const match=image.data.match(/^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/]*={0,2})$/);if(!match||match[1]!==image.mime||match[2].length%4)throw Error('备份照片格式不正确');let raw;try{raw=Uint8Array.from(atob(match[2]),c=>c.charCodeAt(0))}catch{throw Error('备份照片编码不正确')}if(raw.length!==image.bytes||await digestBytes(raw)!==image.sha256)throw Error('备份照片校验失败');attachments.push({...meta,blob:new Blob([raw],{type:image.mime})});}if(row.withdrawn){if(row.content||attachments.length)throw Error('已撤回备份不得含正文或照片')}else{const canonical={version:1,id:row.id,content:row.content,attachments:attachments.map(({id,mime,bytes,sha256})=>({id,mime,bytes,sha256}))};if(await digestBytes(new TextEncoder().encode(JSON.stringify(canonical)))!==item.payloadHash)throw Error('备份正文校验失败');}result.push({key:key+'\n'+row.id,scopeKey:key,messageId:row.id,row,attachments,payloadHash:item.payloadHash,savedAt:item.savedAt,serverConfirmed:false,importedAt:new Date().toISOString(),bytes:new TextEncoder().encode(JSON.stringify(row)).length+attachments.reduce((n,a)=>n+a.bytes,0)});}return result;}
async function importLocalArchive(file){const e=epoch,key=localScope?.key,control=$('comms-local-import');if(!key||!file)return;if(localOffline||navigator.onLine===false){archiveStatus('导入需联网核对账号和撤回状态；不会重新发送消息。',true);return;}control.disabled=true;archiveStatus('正在校验备份和服务器状态，不会发送消息…');try{const entries=await validateBackup(file,key,e),existing=new Map((await localAll(key)).map(r=>[r.messageId,r]));for(const record of entries){if(!localGuard(e,key))return;const server=await api('/api/store-communication/local-status?messageId='+encodeURIComponent(record.messageId));if(!localGuard(e,key)||stableScope(server.scope)?.key!==key)throw Error('账号或门店已变化');if(server.payloadHash&&server.payloadHash!==record.payloadHash)throw Error('备份与服务器内容校验不一致');if(!server.contentAvailable&&!server.cloudCleaned||existing.get(record.messageId)?.row.withdrawn||rows.get(record.messageId)?.withdrawn){record.row={...record.row,withdrawn:true,content:'',attachments:[]};record.attachments=[];record.bytes=new TextEncoder().encode(JSON.stringify(record.row)).length;}else if(existing.get(record.messageId)?.payloadHash===record.payloadHash)Object.assign(record,existing.get(record.messageId));}if(!localGuard(e,key))return;const db=await localDb();await new Promise((resolve,reject)=>{const tx=db.transaction('messages','readwrite');for(const record of entries)tx.objectStore('messages').put(record);tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(Error('本机导入未完成，可能空间不足'));});if(localGuard(e,key)){await renderLocalArchive();archiveStatus('已导入 '+entries.length+' 条本机副本；没有重新发送、标读或确认服务器保存。')}}catch(error){if(localGuard(e,key))archiveStatus('备份未导入：'+error.message,true)}finally{control.disabled=false}}
function mountLocalArchive(){localDialog=make('dialog',undefined,'comms-local-dialog');localDialog.id='comms-local-dialog';const header=make('header',undefined,'comms-local-header');header.append(make('h2','本机消息与照片'));const close=make('button','关闭');close.type='button';close.onclick=()=>localDialog.close();header.append(close);localDialog.append(header,make('p','只查看当前账号、本店的本机副本。清理浏览器数据、换手机可能丢失，请导出备份。断网时不能发送或确认回执。','comms-local-note'));const controls=make('div',undefined,'comms-local-tools'),search=make('input');search.id='comms-local-search';search.type='search';search.placeholder='搜索消息或姓名';search.setAttribute('aria-label','搜索本机消息');search.oninput=()=>renderLocalArchive();const exp=make('button','导出备份');exp.type='button';exp.id='comms-local-export';exp.onclick=exportLocalArchive;const reload=make('button','刷新本机记录');reload.type='button';reload.onclick=renderLocalArchive;const imp=make('button','导入备份'),file=make('input');imp.type='button';imp.id='comms-local-import';file.type='file';file.accept='.json,application/json';file.hidden=true;file.onchange=()=>{void importLocalArchive(file.files[0]);file.value=''};imp.onclick=()=>file.click();controls.append(search,exp,imp,file,reload);localDialog.append(controls);const state=make('p','','comms-local-note');state.id='comms-local-archive-status';state.setAttribute('role','status');localDialog.append(state);const contents=make('div');contents.id='comms-local-rows';localDialog.append(contents);document.body.append(localDialog);localDialog.setAttribute('data-reading-size',String(readingPreferences.fontSize==='auto'?26:readingPreferences.fontSize));localDialog.setAttribute('data-reading-color',readingPreferences.color);}
function activeImages(){return imageDrafts.get(peer)||[];}
function renderImageDrafts(){const box=$('comms-image-previews');if(!box)return;const run=++localPreviewRun;box.replaceChildren();const drafts=activeImages();$('comms-send').querySelector('.comms-photo-options').open=drafts.length>0;$('comms-content').required=!drafts.length;for(const image of drafts){const figure=make('figure',undefined,'comms-image-preview'),canvas=make('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','发送前照片预览');const remove=make('button','移除');remove.type='button';remove.onclick=()=>{imageDrafts.set(peer,activeImages().filter(entry=>entry.id!==image.id));renderImageDrafts()};figure.append(canvas,make('figcaption',image.name+' · '+bytesText(image.blob.size)),remove);box.append(figure);void paintBlob(canvas,image.blob).catch(()=>{if(run===localPreviewRun)figure.append(make('p','照片预览失败，请移除后重新选图。'))})}}
async function compressImage(file){if(!allowedImageTypes.has(file.type))throw Error('仅支持 JPG、PNG、WebP 照片；其他格式请先转换');if(file.size>20000000)throw Error('原照片超过20MB，请先缩小');if(typeof createImageBitmap!=='function')throw Error('此浏览器不能处理照片，请换用更新的浏览器');const bitmap=await createImageBitmap(file);try{if(!bitmap.width||!bitmap.height||bitmap.width*bitmap.height>80000000)throw Error('照片尺寸过大');const canvas=make('canvas');let side=1600,quality=.84,blob;for(let attempt=0;attempt<12;attempt++){const scale=Math.min(1,side/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',quality));if(blob?.size&&blob.size<=localImageLimit)return {id:crypto.randomUUID(),name:String(file.name||'照片').replace(/\.[^.]*$/,'').slice(0,90)+'.jpg',blob,data:await blobData(blob)};quality=Math.max(.45,quality-.1);if(quality<=.45)side=Math.round(side*.78);}throw Error('照片无法压缩到发送大小，请换一张')}finally{bitmap.close()}}
async function addImageFiles(files){if(blocked||localOffline||imageInputBusy)return;const target=peer,e=epoch,key=localScope?.key,list=[...files];if(!list.length)return;if(activeImages().length+list.length>3){status('每条消息最多3张照片；可移除后再选。',true);return;}const controls=[$('comms-image-pick'),$('comms-image-camera')];imageInputBusy=true;controls.forEach(n=>n.disabled=true);status('正在压缩照片，尚未发送…');try{for(const file of list){const image=await compressImage(file);if(!valid(e)||localScope?.key!==key)return;const drafts=imageDrafts.get(target)||[];if(drafts.length>=3)throw Error('每条消息最多3张照片');imageDrafts.set(target,[...drafts,image]);}if(valid(e)&&peer===target){renderImageDrafts();status('照片已放入草稿；请确认看得清楚，再点“发送”。')}}catch(error){if(valid(e))status('选图失败：'+error.message,true)}finally{imageInputBusy=false;controls.forEach(n=>n.disabled=false)}}
function mountLocalControls(){
 mountLocalArchive();const entry=make('button','本机记录');entry.id='comms-local-open';entry.type='button';entry.onclick=showLocalArchive;panel.querySelector('.comms-read-tools').append(entry);const state=make('p','','comms-local-note');state.id='comms-local-status';state.setAttribute('role','status');$('comms-reading-controls').append(state);
 const tools=make('div',undefined,'comms-image-tools');for(const [id,title,camera] of [['comms-image-pick','选照片',false],['comms-image-camera','拍照片',true]]){const control=make('button',title);control.id=id;control.type='button';const input=make('input');input.type='file';input.accept=camera?'image/jpeg':'image/jpeg,image/png,image/webp';input.hidden=true;input.multiple=!camera;if(camera)input.setAttribute('capture','environment');input.onchange=()=>{void addImageFiles(input.files);input.value=''};control.onclick=()=>input.click();tools.append(control,input)}const kind=make('select');kind.id='comms-message-kind';kind.setAttribute('aria-label','消息用途');for(const [value,title]of [['work','工作消息'],['chat','普通聊天']]){const opt=make('option',title);opt.value=value;kind.append(opt)}const important=make('label',undefined,'comms-message-important'),check=make('input');check.type='checkbox';check.id='comms-message-important';important.append(check,make('span','重要内容'));tools.append(kind,important);const previews=make('div',undefined,'comms-image-previews');previews.id='comms-image-previews';const details=make('details',undefined,'comms-photo-options');details.append(make('summary','照片'),tools,previews);$('comms-content').after(details);const note=make('p','最多3张；可粘贴图片。选图、拍照只进入草稿，点发送才上传。工作和重要消息不自动清云。','comms-local-note');details.append(note);$('comms-content').addEventListener('paste',event=>{const files=[...(event.clipboardData?.files||[])].filter(file=>file.type.startsWith('image/'));if(files.length){event.preventDefault();void addImageFiles(files)}});
 window.addEventListener('storage',event=>{if(event.key==='store-session-logout-v1'){clearLocalUi();localScope=null;try{sessionStorage.removeItem(localPointerKey)}catch{}}});window.addEventListener('offline',()=>localHint('当前断网；可查看本机记录，发送和回执需联网。',true));
}
function clearLocalUi(){localNext=null;imageDrafts.clear();localPreviewRun++;localDialog?.close();$('comms-local-rows')?.replaceChildren();$('comms-image-previews')?.replaceChildren();}
async function mountOfflineLocal(error){if(error?.status||document.documentElement.classList.contains('customer-mode')||document.body.classList.contains('signed-out'))return false;try{const pointer=JSON.parse(sessionStorage.getItem(localPointerKey));if(!pointer||pointer.logoutMarker!==localStorage.getItem('store-session-logout-v1')||pointer.identity?.status!=='active')return false;me=pointer.identity;localScope=stableScope(pointer.scope);if(!localScope)return false;localOffline=true;restoreReadingPreferences();mountLocalArchive();const entry=make('button','查看本机消息（离线）','comms-offline-entry');entry.type='button';entry.onclick=showLocalArchive;document.body.append(entry);window.addEventListener('storage',event=>{if(event.key==='store-session-logout-v1'){entry.remove();localDialog.close();localDialog.remove();localScope=null;try{sessionStorage.removeItem(localPointerKey)}catch{}}});return true}catch{return false}}

async function api(path,body,key){const res=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','Idempotency-Key':key||crypto.randomUUID()}:undefined,body:body?JSON.stringify(body):undefined});const data=await res.json().catch(()=>({}));if(!res.ok){const error=Error(res.status===401?'登录已失效，请重新登录':data.error?.message||'读取失败，请重试');error.status=res.status;throw error;}return data;}
async function post(path,body){const signature=JSON.stringify(body);if(retryKeys.get(path)?.signature!==signature)retryKeys.set(path,{signature,key:crypto.randomUUID()});const data=await api(path,body,retryKeys.get(path).key);retryKeys.delete(path);return data;}
const stamp=at=>new Date(at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const valid=(e,v=version)=>!blocked&&e===epoch&&v===version;
function status(text,error=false){$('comms-status').textContent=text;$('comms-status').classList.toggle('error',error);const intro=$('comms-screen-intro');if(intro&&!$('comms-notice-view').hidden){intro.textContent=text||'选择一条通知编辑，系统按设定时间播放。';intro.classList.toggle('error',error);}}
function clear(){clearBusinessNotices();clearLocalUi();clearWorkflow();stopBoard();rows.clear();for(const id of ['comms-rows','comms-announcements','comms-managed','comms-history'])$(id).replaceChildren();$('comms-content').value='';messageDrafts.clear();resetNoticeForm();retryKeys.clear();previews=[];lastUnread=0;clearInterval(previewTimer);$('comms-preview-text').textContent='';$('comms-preview-sender').textContent='';status('');}
function disconnect(){stream?.close();stream=null;streamReady=false;}
function connectionHint(text){if($('comms-connection'))$('comms-connection').textContent=text;}
function disable(){blocked=true;epoch++;disconnect();button.hidden=true;panel.hidden=true;placeComposer();if(board)board.hidden=true;clear();viewportForTyping();}
function connect(){
 if(blocked||document.hidden||stream||!window.EventSource)return;
 stream=new EventSource('/api/store-communication/events');
 stream.addEventListener('ready',()=>{streamReady=true;connectionHint('');refresh();schedule();});
 stream.addEventListener('changed',()=>{if(busy)pending=true;else refresh();});
 stream.addEventListener('auth-expired',disable);
 stream.onerror=()=>{streamReady=false;connectionHint('重连中');schedule();};
}
const frameLayouts={mini:null,panel:null,icon:null};let miniCollapsedHeight=160,frameGesture=null,symbolCollapsed=true,symbolTapAt=0,compactStage=0;
const frameStorageKey=()=>me?.id?'store-message-frame-v1:'+encodeURIComponent(me.id):null;
function frameBounds(){const vv=window.visualViewport;return {left:(vv?.offsetLeft||0)+8,top:(vv?.offsetTop||0)+8,width:Math.max(1,(vv?.width||innerWidth)-16),height:Math.max(1,(vv?.height||innerHeight)-16)};}
function frameNode(name){return name==='mini'||name==='icon'?button:panel;}
function boundedFrame(name,value){const b=frameBounds();if(name==='icon'){const width=Math.min(64,b.width),height=Math.min(64,b.height);return {left:Math.max(b.left,Math.min(b.left+b.width-width,value.left)),top:Math.max(b.top,Math.min(b.top+b.height-height,value.top)),width,height};}const minWidth=Math.min(name==='mini'?224:300,b.width),minHeight=Math.min(name==='mini'?(miniCollapsed?144:280):420,b.height);const width=Math.min(b.width,Math.max(minWidth,value.width)),height=Math.min(b.height,Math.max(minHeight,value.height));return {left:Math.max(b.left,Math.min(b.left+b.width-width,value.left)),top:Math.max(b.top,Math.min(b.top+b.height-height,value.top)),width,height};}
function saveFrameLayouts(){try{const key=frameStorageKey();if(key)localStorage.setItem(key,JSON.stringify({mini:frameLayouts.mini,panel:frameLayouts.panel,icon:frameLayouts.icon,symbolCollapsed,compactStage,miniCollapsed,miniExpandedHeight:miniSize.height,miniCollapsedHeight}));}catch{}}
function restoreFrameLayouts(){try{const saved=JSON.parse(localStorage.getItem(frameStorageKey()));compactStage=saved?.symbolCollapsed===false&&[1,2].includes(saved?.compactStage)?saved.compactStage:0;symbolCollapsed=compactStage===0;if(typeof saved?.miniCollapsed==='boolean')miniCollapsed=saved.miniCollapsed;for(const name of ['mini','panel','icon']){const value=saved?.[name];if(value&&['left','top','width','height'].every(key=>Number.isFinite(value[key]))){frameLayouts[name]=boundedFrame(name,value);if(name==='mini')miniSize.width=frameLayouts[name].width;}}if(Number.isFinite(saved?.miniExpandedHeight))miniSize.height=Math.max(280,Math.min(1200,saved.miniExpandedHeight));if(Number.isFinite(saved?.miniCollapsedHeight))miniCollapsedHeight=Math.max(144,Math.min(1200,saved.miniCollapsedHeight));}catch{}}
function placeFrame(name,value,save=false){const node=frameNode(name);if(!node||name==='mini'&&symbolCollapsed||name==='panel'&&node.classList.contains('is-expanded'))return;const next=boundedFrame(name,value);frameLayouts[name]=next;node.classList.add('is-frame-positioned');for(const key of ['left','top','width','height'])node.style.setProperty('--comms-frame-'+key,next[key]+'px');if(name==='mini'){miniSize.width=next.width;if(miniCollapsed)miniCollapsedHeight=next.height;else miniSize.height=next.height;document.body.style.setProperty('--comms-mini-height',next.height+'px');}node.classList.toggle('is-frame-small',next.height<600);applyFrameReading();if(save)saveFrameLayouts();}
function currentFrame(name){const r=frameNode(name).getBoundingClientRect();return {left:r.left,top:r.top,width:r.width,height:r.height};}
function fitFrames(){if(symbolCollapsed&&button&&!button.hidden)placeFrame('icon',frameLayouts.icon||currentFrame('icon'));for(const name of ['mini','panel']){const node=frameNode(name);if(node&&!node.hidden&&!node.classList.contains('is-expanded'))placeFrame(name,frameLayouts[name]||currentFrame(name));}applyFrameReading();}
